INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Vertraulichkeit nur für sensible Daten wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Daten sollten geschützt werden"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt am besten vor unbefugtem Zugriff?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Macht Daten unlesbar"}, {"text": "Passwortlänge", "correct": false, "because": "Nur ein Teilaspekt"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gewährleisten Vertraulichkeit?', 5, '[{"text": "TLS", "correct": true, "because": "Sichert Datenübertragung"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "Schnelle Server", "correct": false, "because": "Kein Schutzmittel"}, {"text": "Große Speicher", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschlüsselung schützt Vertraulichkeit. b) Sie ist nur für Netzwerke nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch lokale Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Sicherung der Vertraulichkeit?', 4, '[{"text": "Zugriffsberechtigungen", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Verschlüsselung", "correct": false, "because": "Hauptmethode"}, {"text": "Farbschema", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Vertraulichkeit auch physische Maßnahmen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. abgeschlossene Räume"}, {"text": "Nein", "correct": false, "because": "Physischer Schutz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel schützt Daten während der Übertragung?', 3, '[{"text": "HTTPS", "correct": true, "because": "Verschlüsselt Kommunikation"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schutz"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze sichern Vertraulichkeit?', 5, '[{"text": "Passwortschutz", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "VPN", "correct": true, "because": "Sichert Netzwerke"}, {"text": "Schnelle CPUs", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Unsortierte Daten", "correct": false, "because": "Kein Sicherheitsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Vertraulichkeit schützt vor Abhören. b) Sie braucht keine Technik. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Vertraulichkeit zu gewährleisten?', 4, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Notwendig für Verschlüsselung"}, {"text": "Authentifizierung", "correct": false, "because": "Sichert Zugriff"}, {"text": "Maximale Speichergröße", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Verschlüsselung die einzige Methode für Vertraulichkeit?', 2, '[{"text": "Nein", "correct": true, "because": "Zugriffskontrollen zählen auch"}, {"text": "Ja", "correct": false, "because": "Mehrere Mittel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien fördern Vertraulichkeit?', 4, '[{"text": "AES", "correct": true, "because": "Starke Verschlüsselung"}, {"text": "SSL", "correct": true, "because": "Sichert Übertragung"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Vertraulichkeit ohne Passwörter möglich ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. durch Verschlüsselung"}, {"text": "Nein", "correct": false, "because": "Passwörter sind nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um Vertraulichkeit zu sichern?', 3, '[{"text": "Zugriffskontrolle", "correct": true, "because": "Verhindert unbefugten Zugang"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Großer Cache", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Vertraulichkeit schützt vor unbefugtem Zugriff. b) Sie ist nur für Datenbanken wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen Vertraulichkeit?', 5, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Erhöht Zugangssicherheit"}, {"text": "End-to-End-Verschlüsselung", "correct": true, "because": "Schützt Übertragung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzmittel"}, {"text": "Unsortierte Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Vertraulichkeit unwichtig?', 3, '[{"text": "Verschlüsselungsstärke", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Zugriffsbeschränkung", "correct": false, "because": "Verhindert Zugriff"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Vertraulichkeit? Ist sie nur technisch?', 3, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Prozesse spielen mit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Vertraulichkeit auch rechtliche Aspekte hat?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. DSGVO verlangt Schutz"}, {"text": "Nein", "correct": false, "because": "Gesetzlich geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel schützt Vertraulichkeit in Netzwerken?', 4, '[{"text": "IPSec", "correct": true, "because": "Verschlüsselt Netzwerkverkehr"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Schutz"}, {"text": "Großer Cache", "correct": false, "because": "Irrelevant"}]');
